/**
 * June 2026 inventory batch — creates the 18-article, 3-pillar series as
 * Sanity post documents with status "draft": a six-month publishing
 * runway. Each draft carries its planned publish date (publishedAt), its
 * category, a branded cover generated by the production /api/og endpoint,
 * and internal links between series articles.
 *
 * Publishing an article = open it in Studio, flip status to "published"
 * (adjust publishedAt if the calendar moved). Publish pillars before
 * their clusters — cluster articles link back to their pillar.
 *
 * Run: node scripts/create-inventory-posts.mjs          (dry run)
 *      node scripts/create-inventory-posts.mjs --apply  (writes to Sanity)
 */

import { createClient } from "@sanity/client";
import dotenv from "dotenv";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import { randomUUID } from "crypto";

const __dirname = dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: join(__dirname, "..", ".env.local") });

const APPLY = process.argv.includes("--apply");
const MILOS_AUTHOR_ID = "47455f55-daea-449c-b813-f1d8d3c4b08b";
const OG_BASE = "https://codefromscratch-ten.vercel.app/api/og";

const CATEGORY_IDS = {
  "Web Development": "category-webdev",
  "JavaScript Frameworks": "hBCThv4cD85OyEoascrI3s",
  Databases: "ASHvuZRwxvLAyUgORdjcF1",
  Security: "jI8fxKUnBFoPpwmJwz1RMp",
  "APIs & Integrations": "hBCThv4cD85OyEoascrQ7Q",
  "Architecture & Patterns": "ASHvuZRwxvLAyUgORdk65v",
  "DevOps & Infrastructure": "hBCThv4cD85OyEoascrSCc",
  "Cloud & Hosting": "hBCThv4cD85OyEoascrLIq",
};

// slug → [category, planned publish date]. Cadence: 1st / 11th / 21st,
// July through December 2026; each pillar opens its month block.
const PLAN = {
  "modern-full-stack-2026": ["Web Development", "2026-07-01"],
  "why-nextjs-app-router": ["JavaScript Frameworks", "2026-07-11"],
  "react-server-components-explained": ["JavaScript Frameworks", "2026-07-21"],
  "prisma-vs-drizzle-decision": ["Databases", "2026-08-01"],
  "nextauth-vs-lucia-vs-better-auth": ["Security", "2026-08-11"],
  "stripe-nextjs-setup": ["APIs & Integrations", "2026-08-21"],
  "production-grade-code-checklist": ["Architecture & Patterns", "2026-09-01"],
  "zod-at-trust-boundaries": ["Architecture & Patterns", "2026-09-11"],
  "api-rate-limiting-nextjs": ["Security", "2026-09-21"],
  "structured-logging-nextjs": ["DevOps & Infrastructure", "2026-10-01"],
  "error-boundaries-done-right": ["JavaScript Frameworks", "2026-10-11"],
  "stripe-webhook-verification": ["APIs & Integrations", "2026-10-21"],
  "ship-nextjs-production": ["Cloud & Hosting", "2026-11-01"],
  "vercel-vs-self-host": ["Cloud & Hosting", "2026-11-11"],
  "managed-postgres-comparison": ["Databases", "2026-11-21"],
  "observability-solo-saas": ["DevOps & Infrastructure", "2026-12-01"],
  "rollback-without-feature-flags": ["DevOps & Infrastructure", "2026-12-11"],
  "domain-ssl-email-dns-setup": ["Cloud & Hosting", "2026-12-21"],
};

const client = createClient({
  projectId: process.env.NEXT_PUBLIC_SANITY_PROJECT_ID,
  dataset: process.env.NEXT_PUBLIC_SANITY_DATASET || "production",
  apiVersion: "2024-01-01",
  token: process.env.SANITY_API_TOKEN,
  useCdn: false,
});

const k = () => randomUUID().slice(0, 12);

function toPortableText(blocks) {
  const out = [];
  for (const b of blocks) {
    switch (b.t) {
      case "lead":
        out.push({ _type: "lead", _key: k(), text: b.text });
        break;
      case "p": {
        const markDefs = [];
        const children = b.rich
          ? b.rich.map((r) => {
              const marks = [];
              if (r.mark) marks.push(r.mark);
              if (r.href) {
                const defKey = k();
                markDefs.push({ _type: "link", _key: defKey, href: r.href });
                marks.push(defKey);
              }
              return { _type: "span", _key: k(), text: r.text, marks };
            })
          : [{ _type: "span", _key: k(), text: b.text, marks: [] }];
        out.push({
          _type: "block",
          _key: k(),
          style: "normal",
          markDefs,
          children,
        });
        break;
      }
      case "h2":
      case "h3":
        out.push({
          _type: "block",
          _key: k(),
          style: b.t,
          markDefs: [],
          children: [{ _type: "span", _key: k(), text: b.text, marks: [] }],
        });
        break;
      case "code":
        out.push({
          _type: "code",
          _key: k(),
          language: b.language,
          code: b.code,
          ...(b.filename ? { filename: b.filename } : {}),
        });
        break;
      case "callout":
        out.push({ _type: "callout", _key: k(), type: b.calloutType, text: b.text });
        break;
      case "bullet":
        for (const item of b.items) {
          out.push({
            _type: "block",
            _key: k(),
            style: "normal",
            listItem: "bullet",
            level: 1,
            markDefs: [],
            children: [{ _type: "span", _key: k(), text: item, marks: [] }],
          });
        }
        break;
      case "divider":
        out.push({ _type: "divider", _key: k(), style: "plain" });
        break;
      default:
        throw new Error(`Unknown block type: ${b.t}`);
    }
  }
  return out;
}

async function uploadCover(title, category) {
  const url = `${OG_BASE}?title=${encodeURIComponent(title)}&category=${encodeURIComponent(category)}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`OG fetch ${res.status} for "${title}"`);
  const buf = Buffer.from(await res.arrayBuffer());
  const asset = await client.assets.upload("image", buf, {
    filename: `cover-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 60)}.png`,
    contentType: "image/png",
  });
  return asset._id;
}

async function main() {
  console.log(`${APPLY ? "APPLY" : "DRY RUN"} — ${Object.keys(PLAN).length} inventory drafts\n`);
  let created = 0;
  for (const [slug, [category, publishDate]] of Object.entries(PLAN)) {
    const draft = JSON.parse(
      readFileSync(join(__dirname, "..", "content-drafts", `draft-${slug}.json`), "utf8"),
    );
    const existing = await client.fetch(
      `*[_type == "post" && slug.current == $slug][0]._id`,
      { slug },
    );
    if (existing) {
      console.log(`skip ${slug} — already exists (${existing})`);
      continue;
    }
    const content = toPortableText(draft.blocks);
    console.log(
      `create ${publishDate}  [${category}]  ${draft.title.slice(0, 58)} — ${content.length} blocks`,
    );
    if (!APPLY) continue;

    const coverAssetId = await uploadCover(draft.title, category);
    await client.create({
      _type: "post",
      title: draft.title,
      slug: { _type: "slug", current: slug },
      status: "draft",
      isPremium: false,
      publishedAt: `${publishDate}T08:00:00.000Z`,
      readingTime: draft.readingTime,
      excerpt: draft.excerpt,
      seoTitle: draft.title,
      seoDescription: draft.excerpt,
      author: { _type: "reference", _ref: MILOS_AUTHOR_ID },
      categories: [
        { _type: "reference", _ref: CATEGORY_IDS[category], _key: k() },
      ],
      content,
      featuredImage: {
        _type: "image",
        asset: { _type: "reference", _ref: coverAssetId },
        alt: draft.title,
      },
    });
    created++;
  }
  const drafts = await client.fetch(
    `count(*[_type == "post" && status == "draft"])`,
  );
  console.log(`\ncreated: ${created}; total draft-status posts now: ${drafts}`);
}

main().catch((e) => {
  console.error(e.message);
  process.exit(1);
});
